/// A named set, as the API carries it.
///
/// **The file on disk is a storage format, not this.** A stored zone set keeps
/// its own spelling — a bound written `"$goal_cm"`, a metric written
/// `"displacement"` — because somebody edits it in a text editor and reviews it
/// in a diff, and `docs/reference/zone-set.schema.json` is its schema. The
/// daemon converts at the same seam it converts everything else, exactly as it
/// does for the TOML rig config.
///
/// This was carried as an opaque document at first, to keep one spelling for
/// both. That put the one part of the API a client most wants to construct
/// beyond the reach of a type, and a schema for it in a second file. The public
/// interface is defined in one place and strongly typed, or it is not; the file
/// keeps its own shape and the daemon pays for the difference.
///
/// Declaration order resolves two zones firing in one scan: both still fire,
/// and the order is the order of their `zone_hit` messages.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ZoneSet {
    /// A URL for this set's JSON Schema, carried so an editor can validate the
    /// *file* as somebody types it. Stored as `$schema`; named for what it is
    /// here, since a leading `$` is a JSON-editor convention and not a field name.
    ///
    /// It exists because the file refuses unknown fields: without somewhere to put
    /// it, the one line that makes a hand-edited file checkable would itself be a
    /// refusal.
    #[prost(string, optional, tag = "1")]
    pub schema_url: ::core::option::Option<::prost::alloc::string::String>,
    /// Bumped by whoever edits the set. The board reports the version it holds, so
    /// "is the board running what I think it is" is one comparison.
    #[prost(uint32, tag = "2")]
    pub zone_set_version: u32,
    #[prost(message, repeated, tag = "3")]
    pub zones: ::prost::alloc::vec::Vec<Zone>,
}
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Zone {
    #[prost(string, tag = "1")]
    pub name: ::prost::alloc::string::String,
    #[prost(enumeration = "ZoneShape", tag = "2")]
    pub shape: i32,
    /// The axes this zone constrains, in the order its bounds are given. One for a
    /// wheel; a 2-D rectangle on a ball is already expressible.
    #[prost(string, repeated, tag = "3")]
    pub axes: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    #[prost(enumeration = "ZoneMetric", tag = "4")]
    pub metric: i32,
    /// The low end per axis, in the order of `axes`.
    #[prost(message, repeated, tag = "5")]
    pub min_cm: ::prost::alloc::vec::Vec<ZoneBound>,
    /// The high end per axis.
    #[prost(message, repeated, tag = "6")]
    pub max_cm: ::prost::alloc::vec::Vec<ZoneBound>,
    /// A circular track: the metric is evaluated modulo this period.
    #[prost(double, optional, tag = "7")]
    pub wrap_cm: ::core::option::Option<f64>,
    #[prost(enumeration = "FireRule", tag = "8")]
    pub fire: i32,
    #[prost(double, optional, tag = "9")]
    pub hysteresis_cm: ::core::option::Option<f64>,
    /// Fire on arming if the animal is already inside. Off by default: a zone
    /// fires on the false→true **edge** of "inside", so arming a zone somebody is
    /// standing in does not fire it.
    #[prost(bool, tag = "10")]
    pub level: bool,
    #[prost(message, optional, tag = "11")]
    pub output: ::core::option::Option<ZoneOutput>,
}
/// One end of a zone's interval on one axis.
///
/// Three things, and they are not interchangeable: a number, an **open** bound
/// (neither arm set — "everything past here"), and a **reference** to a
/// per-trial value resolved from the patch given at arm time.
///
/// A reference that reaches the compiler unresolved is a refusal naming the
/// name, never a zero: a goal distance that silently became zero is a trial that
/// looks like it ran. The board never sees a reference; substitution happens
/// host-side, before compilation.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ZoneBound {
    #[prost(oneof = "zone_bound::Bound", tags = "1, 2")]
    pub bound: ::core::option::Option<zone_bound::Bound>,
}
/// Nested message and enum types in `ZoneBound`.
pub mod zone_bound {
    #[derive(Clone, PartialEq, ::prost::Oneof)]
    pub enum Bound {
        #[prost(double, tag = "1")]
        Value(f64),
        /// The name without its `$`. The file writes `"$goal_cm"`; the sigil is the
        /// file's way of telling a number from a name in one JSON position, and the
        /// oneof is this interface's.
        #[prost(string, tag = "2")]
        Reference(::prost::alloc::string::String),
    }
}
