/// What a zone is doing right now.
///
/// The bounds are **as armed**, in centimetres: the `$name`s resolved from the
/// trial's patch and the counts the board is actually comparing against,
/// converted back. Without them a UI can only draw the set as *stored*, which
/// for a parameterised set is a picture of a zone that is not the one running —
/// and "is the reward region where I think it is" is the question the picture
/// exists to answer.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ZoneStatus {
    #[prost(string, tag = "1")]
    pub name: ::prost::alloc::string::String,
    #[prost(bool, tag = "2")]
    pub armed: bool,
    #[prost(bool, tag = "3")]
    pub fired: bool,
    #[prost(bool, tag = "4")]
    pub inside: bool,
    #[prost(double, optional, tag = "5")]
    pub fired_at_cm: ::core::option::Option<f64>,
    /// Per axis, in the order the zone names them. An absent value is an open
    /// bound — everything past the other end.
    ///
    /// A **resolved** bound, deliberately a different type from `ZoneBound`: what
    /// is armed can no longer be a `$name`, and the type saying so is the point of
    /// having types.
    #[prost(message, repeated, tag = "6")]
    pub min_cm: ::prost::alloc::vec::Vec<ResolvedBound>,
    #[prost(message, repeated, tag = "7")]
    pub max_cm: ::prost::alloc::vec::Vec<ResolvedBound>,
    /// The period the metric is taken modulo, if the zone wraps.
    #[prost(double, optional, tag = "8")]
    pub wrap_cm: ::core::option::Option<f64>,
    #[prost(enumeration = "ZoneMetric", tag = "9")]
    pub metric: i32,
}
/// A bound that may be open, after arming resolved it.
///
/// protobuf has no nullable double inside a repeated field, and a repeated
/// `optional double` is not a thing, so the absence has to be carried by a
/// message: `{"value": 30}` or `{}`.
#[derive(Clone, Copy, PartialEq, ::prost::Message)]
pub struct ResolvedBound {
    #[prost(double, optional, tag = "1")]
    pub value: ::core::option::Option<f64>,
}
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ValidationReport {
    #[prost(bool, tag = "1")]
    pub ok: bool,
    /// The first thing wrong, in the words the compiler would use. Absent when it
    /// compiles.
    #[prost(string, optional, tag = "2")]
    pub problem: ::core::option::Option<::prost::alloc::string::String>,
    #[prost(uint32, tag = "3")]
    pub zone_count: u32,
    /// The calibration it was compiled against, so a report is readable a day
    /// later without guessing which one was in force.
    #[prost(double, tag = "4")]
    pub counts_per_cm: f64,
    /// The `$name`s this set still needs at arm time.
    #[prost(string, repeated, tag = "5")]
    pub references: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
}
